import java.util.Scanner;

public class PalindromeSpecialCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a word: ");
        String word = sc.next().toUpperCase();

        String rev = "";
        for (int i = word.length() - 1; i >= 0; i--) {
            rev = rev + word.charAt(i);
        }

        boolean isPalin = word.equals(rev);
        boolean isSpecial = (word.charAt(0) == word.charAt(word.length() - 1));

        if (isPalin && isSpecial) {
            System.out.println(word + " is both a PALINDROME and a SPECIAL WORD");
        } else if (isSpecial) {
            System.out.println(word + " is a SPECIAL WORD but not a PALINDROME");
        } else {
            System.out.println(word + " is NEITHER a PALINDROME nor a SPECIAL WORD");
        }
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name | Data Type | Purpose
word          | String    | Input word converted to uppercase
rev           | String    | Stores reversed word
isPalin       | boolean   | Flag indicating palindrome match
isSpecial     | boolean   | Flag indicating matching first and last chars
i             | int       | Loop index for reverse traversal
*/
